
public class T0E1 {
	//PROCESOS
    public static void uno_cien() {
        int i = 0;
        while(i < 100) {
            i = i + 1;
            System.out.print(i + ", ");
        }
    }
  //PROGRAMA PRINCIPAL
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Serie del 1 al 100: ");
        uno_cien();
	}

}
